insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/en/24300', E'en', 33, E'Okayama Cherry Blossoms: 10 Scenic Spots, Festivals, and Light-ups', E'This guide covers Okayama\'s famous cherry blossom spots, from classic locations like Korakuen Garden and Tsuyama Castle to hidden gems. We\'ve also provided detailed information on blooming periods and peak viewing times.\n\nIn Okayama, the main cherry blossom spots typically reach their peak from late March to mid-April. This is when various types of cherry trees such as Somei Yoshino, yaezakura (double-flowered cherry), and shidarezakura (weeping cherry) bloom beautifully.\n\nOkayama boasts numerous cherry blossom viewing locations, each hosting events such as daytime, nighttime illuminations, and festivals.\n\nIn Okayama, cherry blossoms typically reach full bloom from late March to mid-April, allowing visitors to enjoy distinctive landscapes at various spots.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226238.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226239.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226241.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226245.webp"]'::jsonb, E'2025-03-11'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/3219', E'en', 34, E'Hiroshima Peace Memorial Park', E'Hiroshima Peace Memorial Park (広島平和記念公園, Hiroshima Heiwa Kinen Kōen) is a memorial park in the center of Hiroshima, Japan.\n\nIt is dedicated to the legacy of Hiroshima as the first city in the world to suffer a nuclear attack at the end of World War II, and to the memories of the bomb\'s direct and indirect victims (of whom there may have been as many as 140,000).\n\nThe Hiroshima Peace Memorial Park is visited by more than one million people each year.\n\nThe park is there in memory of the victims of the nuclear attack on August 6, 1945, in which the United States dropped an atomic bomb on the Japanese city of Hiroshima.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/10/31-131242.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/23-143917.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/08-142860.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/08-142861.webp"]'::jsonb, E'2018-06-26'::timestamptz, E'Hiroshima Peace Memorial Park', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Hiroshima_Peace_Memorial_Park'),
(E'https://matcha-jp.com/en/26999', E'en', 34, E'Hiroshima Peace Memorial Park', E'Hiroshima Peace Memorial Park (広島平和記念公園, Hiroshima Heiwa Kinen Kōen) is a memorial park in the center of Hiroshima, Japan.\n\nIt is dedicated to the legacy of Hiroshima as the first city in the world to suffer a nuclear attack at the end of World War II, and to the memories of the bomb\'s direct and indirect victims (of whom there may have been as many as 140,000).\n\nThe Hiroshima Peace Memorial Park is visited by more than one million people each year.\n\nThe park is there in memory of the victims of the nuclear attack on August 6, 1945, in which the United States dropped an atomic bomb on the Japanese city of Hiroshima.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261781.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261795.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261796.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261783.webp"]'::jsonb, E'2026-03-28'::timestamptz, E'Hiroshima Peace Memorial Park', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Hiroshima_Peace_Memorial_Park'),
(E'https://matcha-jp.com/en/24214', E'en', 34, E'Hiroshima Cherry Blossoms: 8 Breathtaking Spots and Hidden Gems', E'Hiroshima is home to many cherry blossom spots that captivate visitors every year. We introduce eight beautiful locations along with peak blooming times and other highlights.\n\nIn Hiroshima, cherry blossoms typically reach their peak between late March and early April. With its mild climate, Hiroshima is home to many cherry blossom spots where you can enjoy the beautiful flowers alongside historic and scenic views.\n\nFor instance, Senkoji Park offers breathtaking views of the Seto Inland Sea combined with stunning cherry blossoms. Large areas such as Sera Kozan Fureai no Sato and Hijiyama Park are also perfect for hanami (cherry blossom viewing).\n\nAdditionally, Ozekiyama Park and Shukkeien Garden provide serene natural settings where you can admire the elegant cherry blossoms.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225332.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225333.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225334.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225335.webp"]'::jsonb, E'2025-03-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/4546', E'en', 35, E'Kikko Park And Kintai Bridge - The Highlights Of Yamaguchi Prefecture', E'Kikko Park in Iwakuni city, near the famous wooden Kintai Bridge, is home to some incredible seasonal views, including delicate cherry blossoms in spring and brilliant red maple leaves in fall.\n\nKikko Park is a well-known cherry blossom spot, located in the Yokoyama district of Iwakuni city in Yamaguchi prefecture. This park was selected as one of the top 100 spots for cherry blossoms viewing in Japan, along with its wooden Kintai bridge.\n\nDuring the Edo period, this park and its surrounding areas belonged to the daimyo who ruled the area. Within the park grounds, there were houses called the Mekatake jutaku (houses for the samurais that served the daimyo) alongside the daimyo\'s own residence. Near the park is the Kikko Shrine the daimyo visited, which is still standing today. You can get a better understanding of the Edo period through these structures.\n\nThis time, we would like to introduce some basic information, access routes, and highlights of Kikko Park.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/06-28138.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/06-28137.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/06-28139.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/06-28140.webp"]'::jsonb, E'2017-09-01'::timestamptz, E'Kintai Bridge', null, null),
(E'https://matcha-jp.com/en/7855', E'en', 35, E'Tsunoshima Bridge', E'Tsunoshima Bridge (Japanese: 角島大橋, Hepburn: Tsunoshima-Ōhashi) is a bridge located in Yamaguchi Prefecture, Japan.\n\nThe 1,780 m (5,840 ft) bridge connects the island of Tsunoshima to mainland Japan.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85279.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85300.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85280.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85281.webp"]'::jsonb, E'2019-09-29'::timestamptz, E'Tsunoshima Bridge', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Tsunoshima_Bridge'),
(E'https://matcha-jp.com/en/23493', E'en', 35, E'Hofu Tenmangu Shrine Plum Blossom Festival 2026: Highlights and Access', E'Visit Hofu Tenmangu, one of Japan\'s major Tenjin Shrines. Explore the famous Yamaguchi Plum Blossom Festival (Ume Matsuri) held every February.\n\nHofu Tenmangu Shrine is a famous shrine dedicated to Tenjin, the deity of learning, and located in Hofu City, Yamaguchi Prefecture.\n\nThe shrine\'s famous Plum Blossom Festival is held annually from mid-February to early March when the plum blossoms are in full bloom, filling the air with their delightful fragrance.\n\nIn 2026, the Hofu Tenmangu Plum Blossom Festival will be held from February 15 to March 1.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217861.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217863.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217864.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217866.webp"]'::jsonb, E'2025-01-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/12008', E'en', 36, E'Naruto Strait', E'Naruto Strait (鳴門海峡, Naruto-kaikyō) is a strait between Awaji Island and Shikoku in Japan.\n\nIt connects Harima Nada, the eastern part of the Inland Sea and the Kii Channel.\n\nA famous feature of the strait is the Naruto whirlpools.In 1950, it was included as part of the Setonaikai National Park.\n\nŌnaruto Bridge, the southern part of the Kobe-Awaji-Naruto Expressway, crosses over it.It was built in 1985, leading to the cessation of ferry services in 1995 due to low demand.Mopeds are forbidden from driving on the bridge for safety reasons.An annual "Whirlpool Opening" celebration is held every year with the arrival of the spring tide by Naruto City\'s tourism association.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/13-139419.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138208.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138207.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138209.webp"]'::jsonb, E'2023-06-05'::timestamptz, E'Naruto Strait', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Naruto_Strait'),
(E'https://matcha-jp.com/en/4169', E'en', 36, E'Awa Odori Festival 2026: Tokushima\'s Summer Dance Festival', E'Experience the Awa Odori Festival 2026 in Tokushima from August 11–15. Discover festival highlights, venue access, and tips to enjoy Japan’s biggest summer dance event.\n\nThe Awa Odori Festival in Tokushima is one of the most famous dance festivals in Japan. Along with Gifu’s Gujo Odori Dance and Akita’s Nishimonai Bon Odori, it has a history of over 400 years and is counted as one of Japan’s three most important Bon Odori Festivals (*1).\n\n*1 Bon or Obon... The custom of remembering ancestors and deceased family by visiting their graves, which is usually performed in August.\n\nDuring the Awa Odori Festival, thousands of people are dancing to the Awa Yoshikono chant "The dancers are fools, and the watchers are fools. If both are fools, then why not dance?"', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21909.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/16-139567.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/16-139568.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/22-21910.webp"]'::jsonb, E'2018-08-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/11055', E'en', 36, E'Shikoku', E'-] , lit.\'four provinces\') is the smallest of the four main islands of Japan.\n\nIt is 225 kilometres (140 miles) long and between 50 and 150 kilometres (30 and 95 miles) wide.\n\n5 million, the least of Japan\'s four main islands.It is south of Honshu and northeast of Kyushu.\n\nShikoku\'s ancient names include Iyo-no-futana-shima (伊予之二名島), Iyo-shima (伊予島), and Futana-shima (二名島), and its current name refers to the four former provinces that make up the island: Awa, Tosa, Sanuki, and Iyo.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/02-260098.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/31-121964.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/30-121860.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/30-121861.webp"]'::jsonb, E'2025-01-22'::timestamptz, E'Shikoku', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Shikoku'),
(E'https://matcha-jp.com/en/3936', E'en', 37, E'Shodoshima Yokai Art Museum', E'The Shodoshima Yokai Art Museum, also known as the Yokai Bijutsukan Art Museum is a small museum in Kagawa prefecture, which is focused on yōkai, supernatural entities in Japanese folklore.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/01-80659.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/26-15046.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/26-15048.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/01-80661.webp"]'::jsonb, E'2017-10-27'::timestamptz, E'Shodoshima Yokai Art Museum', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Shodoshima_Yokai_Art_Museum'),
(E'https://matcha-jp.com/en/27000', E'en', 37, E'[Trip To Japan] A one-day guided tour of Naoshima\'s art scene', E'This guide introduces an efficient way to visit Naoshima\'s main art spots. It highlights the appeal of a tour that allows you to experience the museums and artworks with explanations about their background, and ensures a worry-free experience including transportation and arrangements.\n\nTo enjoy Naoshima to the fullest, we recommend a guided tour from "Trip To Japan".\n\nThis is not just a place to look at artworks; it\'s a journey of understanding and exploration.\n\nThe biggest appeal of this tour is the presence of a guide with specialized knowledge.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261802.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261803.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261804.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261805.webp"]'::jsonb, E'2026-03-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/24642', E'en', 37, E'Kotohiragu Shrine: 7 Must-Visit Shops and Dining Spots in Kagawa', E'Kotohiragu Shrine in Kagawa Prefecture is a popular destination renowned as a spiritual hotspot. There are also many charming shops along the shrine\'s main approach path. This article, penned by a local MATCHA writer, will introduce seven highly recommended shops.\n\nKotohiragu Shrine, located in Kagawa Prefecture\'s Kotohira Town, is a spiritual hotspot beloved by the nickname "Konpira-san." Since the Edo period, it has been a popular pilgrimage site alongside Ise Shrine, attracting many visitors.\n\nAlong the main approach path leading to Konpira-san, there are many attractions ranging from historic sake breweries to trendy shops. This article introduces the latest recommended spots for 2025.\n\nNakano Udon School is a facility where you can experience making Sanuki udon by hand. In roughly 50 minutes, you will learn the process of making udon from flour and salt water before cooking it.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/04/08-230467.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/19-231558.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/20-231566.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/20-231567.webp"]'::jsonb, E'2025-04-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/23051', E'en', 38, E'Shikoku', E'-] , lit.\'four provinces\') is the smallest of the four main islands of Japan.\n\nIt is 225 kilometres (140 miles) long and between 50 and 150 kilometres (30 and 95 miles) wide.\n\n5 million, the least of Japan\'s four main islands.It is south of Honshu and northeast of Kyushu.\n\nShikoku\'s ancient names include Iyo-no-futana-shima (伊予之二名島), Iyo-shima (伊予島), and Futana-shima (二名島), and its current name refers to the four former provinces that make up the island: Awa, Tosa, Sanuki, and Iyo.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/02-213232.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/06-213788.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/02-213233.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/02-213235.webp"]'::jsonb, E'2024-12-02'::timestamptz, E'Shikoku', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Shikoku'),
(E'https://matcha-jp.com/en/10574', E'en', 38, E'Snap Unique Railroad Photos in Shikoku! 3 Scenic Spots', E'Surrounded by the Seto Inland Sea and the Pacific Ocean, Shikoku is an island known for its pristine landscapes. You can snap railroad photos with stunning natural backdrops, including the sea, mountains, and rivers. We introduce three photo spots in Tokushima and Ehime.\n\nShikoku is an island that sits between the Seto Inland Sea and the Pacific Ocean, with the Shikoku Mountains running through its center. You\'ll find an array of colorful scenery that\'s woven by the sea, mountains, and rivers. Shikoku also has many spots for taking unique train photos!\n\nIn this article, our Shikoku-based writer will introduce three of these spots found in Tokushima and Ehime.\n\nAll of the locations introduced in this article are accessible by JR Shikoku railway lines. These feature colorfully decorated railcars such as the Anpanman Train, and sightseeing cars like the Iyonada Monogatari and the Shikoku Mannaka Sennen Monogatari. They will both delight your eyes and make for a fun ride!', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123702.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123703.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123704.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123705.webp"]'::jsonb, E'2021-07-13'::timestamptz, E'Shikoku', null, null),
(E'https://matcha-jp.com/en/8304', E'en', 38, E'Matsuyama Castle, Hot Springs, and Superb Views! Ehime Travel Guide', E'Nestled in the Shikoku region, Ehime is home to a variety of sightseeing locations, notably Matsuyama Castle and therapeutic hot springs. This article will focus on the tourist-favorite Dogo Onsen in Matsuyama and the scenic Seto Inland Sea islands near Imabari.\n\nEhime Prefecture is located in the northwestern Shikoku region. Matsuyama Castle, Dogo Onsen, and Shimanami Kaido are highlights of this popular travel destination.\n\nThis article will cover the sites of Dogo Onsen in Matsuyama City and the Seto Inland Sea islands near Imabari City.\n\nLocated in central Ehime, Matsuyama City\'s Dogo Onsen area is home to the prefecture\'s most noteworthy sightseeing locations. The six following sites should be on the top of your travel itinerary when visiting Ehime.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/11/18-90836.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/18-90827.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/18-90829.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/18-90832.webp"]'::jsonb, E'2020-01-02'::timestamptz, E'Matsuyama Castle', null, null),
(E'https://matcha-jp.com/en/7851', E'en', 39, E'10 Things To Do In Kochi: Scenic Spots, History, And Cuisine', E'Kochi Prefecture is located in Japan’s Shikoku Island. It is a less touristy place full of stunning nature, history, and delicious food. In this article, we introduce ten places to explore, things to do, and local dishes to taste in Kochi.\n\nKochi, located in Japan’s Shikoku Island, is famous for scenic nature and delicious skipjack tuna as well as for its yuzu production. Kochi also boasts a rich history with one of Japan\'s most famous samurai, Ryoma Sakamoto, being born in here.\n\nPrior to the Meiji Restoration, Kochi was known as the Tosa Province. Nowadays, there still is a city named Tosa in Kochi Prefecture.\n\nWe introduce ten activities and things to enjoy in Kochi, a beautiful though lesser-known region of Japan.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85065.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85062.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/03-85127.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/29-84869.webp"]'::jsonb, E'2019-08-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7820', E'en', 39, E'KITKAT x Yuzu Liqueur! Delicious Bijofu Sake From Kochi Meets Chocolate', E'KITKAT Mini Yuzu-shu Bijofu is the newest addition to the KITKAT Sake series after KITKAT Mini Japanese Sake Masuizumi and KITKAT Mini Umeshu Tsuru-Ume.This chocolate is made in cooperation with Kochi prefecture, famous for its yuzu production, and Bijofu breweries excellent yuzu liqueur\n\nNestlé Japan offers the widest variety of KITKAT-flavors in the world. With seasonal as well as monthly product releases, KITKAT chocolates are some of the most popular souvenirs from Japan.\n\nTwo years ago, KITKAT introduced their Japanese sake series to introduce the delicious flavor of Japanese sake and liquor to the world through KITKAT chocolate. After releasing the KITKAT Japanese SAKE in 2017 and the KITKAT Umeshu (plum wine) in 2018, they are releasing a KITKAT Yuzu-shu Bijofu with real yuzu infused sake 2019. To create this new product, KITKAT teamed up with breweries from Kochi, a region that is famous for its production of yuzu (Asian citrus fruit).\n\nThe former name of Kochi Prefecture is Tosa. Tosa and its famous samurai Sakamoto Ryoma played an important historical role in ending the reign of feudal lords in Japan. One of the most famous sites in Kochi is Kochi Castle.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85062.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/25-84579.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/25-84580.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/03-85114.webp"]'::jsonb, E'2019-08-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/4186', E'en', 39, E'Kochi Castle - An Elegant Castle From The Edo Period', E'Kochi Castle, located in Kochi prefecture, a part of the Shikoku Region, is known for its precious architecture dating back to the Edo Period.\n\nKochi Castle is located in Kochi City, Kochi prefecture, in the Shikoku Region. The castle was built by Yamauchi Kazutoyo, who ruled the Kochi area about 400 years ago. The castle, famous for its elegant tenshu (*1), the massive walls and gates, is known as the "best castle in the Nankaido (*2)". It is also precious as the tenshu and honmaru goten (*3), built in the Edo Period, still remain, and it has been chosen as one of Japan\'s Top 100 Castles.\n\nThe original tenshu, built by Yamauchi Kazutoyo, was lost to the fire in 1727. The tenshu was rebuilt according to the original plan in 1749. Since then, the castle has survived natural disasters, the Ordinance for the Disposal of Castles (*4) issued by the Meiji Government and World War II. Due to that history, the castle is also known as a "Castle of Fortune".\n\nThis article is about the Kochi Castle, a landmark of the Shikoku Region, and its highlights.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21572.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21557.webp"]'::jsonb, E'2017-05-09'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/6301', E'en', 40, E'Kyushu', E'ɕɨ̀ɨ̀] , lit.\'nine provinces\') is the third-largest and most southerly of Japan\'s four main islands.\n\nIn the past, it has been known as Kyūkoku (九国, "Nine Countries"), Chinzei (鎮西, "West of the Pacified Area") and Tsukushi-no-shima (筑紫島, "Island of Tsukushi").\n\nThe historical regional name Saikaidō (西海道; lit.West Sea Circuit) referred to Kyushu and its surrounding islands.\n\nKyushu has a land area of 36,782 square kilometres (14,202 sq mi) and a population of 12,382,121 as of 2025.There is a theory that Kyushu was in ancient times home to its own independent dynasty, where a unique, southern-influenced culture and tradition distinct from that of Honshu flourished.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/09-58093.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58103.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58104.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58105.webp"]'::jsonb, E'2018-08-20'::timestamptz, E'Kyushu', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kyushu'),
(E'https://matcha-jp.com/en/2624', E'en', 40, E'Fukuoka City Museum', E'Fukuoka City Museum (福岡市博物館, Fukuoka-shi hakubutsukan) opened in Fukuoka, Japan, in 1990.\n\nThe permanent exhibition, which tells the history of Fukuoka, is arranged in eleven sections, including those focussing upon the King of Na gold seal (National Treasure), the Kuroda clan, and the Hakata Gion Yamakasa.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/23-193732.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46857.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/30-133408.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/10-122517.webp"]'::jsonb, E'2018-12-17'::timestamptz, E'Fukuoka City Museum', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Fukuoka_City_Museum'),
(E'https://matcha-jp.com/en/1516', E'en', 40, E'Hakata Ramen Complete Guide: What It Is and Where to Try It in Japan', E'Hakata ramen is a local variety of ramen that originates from Fukuoka in southern Japan. Learn how to order and eat it, recommended restaurants in Tokyo and Fukuoka, and the unique characteristics of Hakata ramen, with its tonkotsu pork bone broth and thin noodles.\n\nRamen has become the representative food of Japan. Although it can be found outside of Japan, too, visitors are highly recommended to try this soul food when they are in Japan. In particular, local ramen varieties exist in areas all over Japan, making it worth to try these delicious dishes here.\n\nOne special variety to try in Japan is Hakata ramen, or tonkotsu ramen. The well-known restaurant Ichiran actually offers Hakata ramen, which is a regional specialty that now enjoys popularity overseas. However, trying it in-person and in Japan will provide the best experience.\n\nThis article will introduce what makes Hakata ramen unique, how to order it like a local, and recommended restaurants where Hakata ramen was first made.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/02/22-71859.webp","https://resources.matcha-jp.com/archive_files/jp/2015/12/tonkotsu_ramen_20151225_a-700x466.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/09-85560.webp","https://resources.matcha-jp.com/archive_files/jp/2015/12/tonkotsu_ramen_20151225eye-700x466.webp"]'::jsonb, E'2016-03-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/7306', E'en', 41, E'Saga Travel Guide – Scenic Spots, Food, And Fun Things To Do', E'Saga is full of things to do and see, from an international hot air balloon festival and rice terraces to shopping. The prefecture is also renowned for its local food, like wagyu beef and seafood. Read to learn what to put on your trip itinerary to Saga.\n\nSaga Prefecture is filled with one-of-a-kind activities and destinations, such as a hot air balloon festival, torii gates that appear to be floating on water, and terraced rice fields. Visitors can keep up with the latest trends at a shopping outlet and a stylish library. Delicious food, including fresh seafood and wagyu beef, is also a must-try in Saga.\n\nAll of these things can be encountered in Saga on Japan\'s southern island of Kyushu. Continue reading this complete guide to Saga to find what you can do and see in this prefecture.\n\nSaga Prefecture is in northern Kyushu, east of Fukuoka, and west of Nagasaki, which is known for Huis Ten Bosch and its charming towns. The yellow pin is Kyushu Saga International Airport.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75929.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75911.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75371.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75372.webp"]'::jsonb, E'2019-06-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/11715', E'en', 41, E'Enjoy Early Cherry Blossoms! 3-Day Spring Itinerary in Fukuoka and Saga', E'Cherry blossoms bloom early in Japan\'s Kyushu region. This three-day spring itinerary in Fukuoka and Saga includes sights, cherry blossoms, travel tips, and wonders of both old and new Japan that can be enjoyed in this area.\n\nWhether they\'re framing the four-hundred-year-old Fukuoka Castle or creating a beautiful backdrop for the magical atmosphere of Mifuneyama, Kyushu\'s cherry blossoms are a unique and unforgettable sight.\n\nRead on to learn about a suggested four-day spring itinerary that includes some of the best locations for viewing the cherry blossoms in Fukuoka and Saga. These destinations are sure to delight any traveler that enjoys a taste of traditional Japan.\n\nIn 2023, the cherry blossoms are expected to start blooming around March 20 in north-western Kyushu. This makes late March the best time for enjoying the itinerary introduced below.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/02/24-135085.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1637.webp","https://resources.matcha-jp.com/resize/720x2000/2023/02/06-134532.webp","https://resources.matcha-jp.com/resize/720x2000/2023/02/24-135083.webp"]'::jsonb, E'2023-02-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/9568', E'en', 40, E'Fukuoka City Museum', E'Fukuoka City Museum (福岡市博物館, Fukuoka-shi hakubutsukan) opened in Fukuoka, Japan, in 1990.\n\nThe permanent exhibition, which tells the history of Fukuoka, is arranged in eleven sections, including those focussing upon the King of Na gold seal (National Treasure), the Kuroda clan, and the Hakata Gion Yamakasa.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127833.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127837.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99807.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99808.webp"]'::jsonb, E'2022-10-27'::timestamptz, E'Fukuoka City Museum', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Fukuoka_City_Museum'),
(E'https://matcha-jp.com/en/23471', E'en', 41, E'Ride the Two Stars 4047 From Nagasaki to Saga: Scenic Views and Sake', E'Ride the JR Kyushu Two Stars 4047 sightseeing train through Saga and Nagasaki. Discover scenic rail routes, premium Japanese sake, and historic hot springs.\n\nTwo Stars 4047 is a scenic sightseeing train operated by JR Kyushu. It journeys along the picturesque coastline of West Kyushu, showcasing Saga and Nagasaki prefectures—the "two stars" of the region\'s tourism.\n\nThe train operates exclusively from Friday through Monday, as well as on select Japanese national holidays. Its itinerary is split into distinct morning and afternoon routes, allowing passengers to experience different coastal views.\n\nThe Morning Route (Saga to Nagasaki) - Departs from Takeo-Onsen in Saga, passes through Hizen-Hama, Tara, and Isahaya stations, and arrives at Nagasaki Station at 13:15.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/06/19-265695.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/27-217618.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/27-217623.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/27-217619.webp"]'::jsonb, E'2026-05-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/19818', E'en', 42, E'Nagasaki Prefectural Art Museum', E'Nagasaki Prefectural Art Museum (長崎県美術館, Nagasaki-ken Bijutsukan) opened in Nagasaki, Nagasaki Prefecture, Japan, in 2005.\n\nThe collection comprises artworks relating to Nagasaki as well as works of Spanish art collected by Suma Yakichiro (須磨弥吉郎), special envoy to Spain during the Second World War.\n\nAlongside the Nagasaki Museum of History and Culture, which opened the same year, it supersedes and replaces the former Nagasaki Prefectural Museum and Art Museum (長崎県立美術博物館), which closed at the end of 2002.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/05/20-180857.webp","https://resources.matcha-jp.com/resize/720x2000/2024/05/20-180840.webp","https://resources.matcha-jp.com/resize/720x2000/2024/05/20-180845.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/24-136275.webp"]'::jsonb, E'2024-05-20'::timestamptz, E'Nagasaki Prefectural Art Museum', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Nagasaki_Prefectural_Art_Museum'),
(E'https://matcha-jp.com/en/9813', E'en', 42, E'Explore Nagasaki by Streetcar: 8 Must-Visit Historical Spots', E'A hilly city, Nagasaki is best explored by streetcar. Check the best places to visit near streetcar stops, from the Peace Park and Dejima, to Oura Catholic Church.\n\nBecause Nagasaki is built on steep hills, you won\'t see many people riding bicycles. Driving can also be a challenge for visitors unfamiliar with the city\'s narrow, winding roads.\n\nFortunately, getting around is easy: you can travel the entire city by streetcar!\n\nThe streetcar fare is a flat 150 yen per ride. You can pay with cash or major public transit IC cards, including Suica and Pasmo.', E'["https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103123.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103124.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103125.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103127.webp"]'::jsonb, E'2021-07-09'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/3323', E'en', 42, E'A First-Timer\'s Guide to Nagasaki: Best Places to Visit and Tips', E'Discover Nagasaki with this ultimate first-timer\'s travel guide. Explore top attractions, local cuisine, transport tips, historic areas, and hotels.\n\nNight view from Mount Inasa in Nagasaki. Photo by Pixta\n\nLocated in northwestern Kyushu, Nagasaki City blends Japanese identity with an international atmosphere.\n\nDuring Japan\'s two centuries of national isolation during the Edo period (1603-1868), Nagasaki prospered as the nation\'s sole gateway to the outside world.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/06/26-266092.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125682.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125679.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125680.webp"]'::jsonb, E'2018-06-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/20733', E'en', 43, E'2026 Kumamoto earthquake', E'9 mi).At least 39 people were killed and more than 170 were injured.\n\nThe Japan Meteorological Agency (JMA) has officially named the earthquake the 2026 Kumamoto earthquake (Japanese: 令和8年熊本地震, Hepburn: Reiwa 8-nen Kumamoto jishin).', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189751.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189750.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189752.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189753.webp"]'::jsonb, E'2024-10-15'::timestamptz, E'2026 Kumamoto earthquake', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/2026_Kumamoto_earthquake'),
(E'https://matcha-jp.com/en/21434', E'en', 40, E'How to Travel from Fukuoka to Kumamoto: By Shinkansen, Train, and Bus', E'Kumamoto\'s popularity as a travel destination has surged in recent years, making transportation between Fukuoka and Kumamoto crucial. This article explores convenient travel options, from the Kyushu Shinkansen to highway buses and trains, to help you choose the best way to reach Kumamoto.\n\nTraveling from Fukuoka to Kumamoto is quite convenient and simple. The main transportation options include the Kyushu Shinkansen, train, and highway bus.\n\nEach mode of transport has advantages and disadvantages. We compare them below so you can choose the route based on your itinerary.\n\nThe fastest train category along the Kyushu Shinkansen is the Mizuho, which takes about 32 minutes to reach Kumamoto. The next stop after Hakata Station is Kumamoto Station, although some trains may stop at Kurume Station.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/26-121632.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-196019.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195939.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/06-195948.webp"]'::jsonb, E'2024-09-25'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/10346', E'en', 43, E'Kumamoto Castle', E'Kumamoto Castle (熊本城, Kumamoto-jō) is a hilltop Japanese castle located in Chūō-ku, Kumamoto, in Kumamoto Prefecture.\n\nIt was a large and well-fortified castle.The castle keep (天守閣, tenshukaku) is a concrete reconstruction built in 1960, but a number of ancillary wooden buildings remain of the original castle.\n\nKumamoto Castle is considered one of the three premier castles in Japan, along with Himeji Castle and Matsumoto Castle.\n\nThirteen structures in the castle complex are designated Important Cultural Property.', E'["https://resources.matcha-jp.com/resize/720x2000/2021/01/26-111949.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/10-112387.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/10-112386.webp","https://resources.matcha-jp.com/resize/720x2000/2021/01/30-112060.webp"]'::jsonb, E'2021-04-27'::timestamptz, E'Kumamoto Castle', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kumamoto_Castle'),
(E'https://matcha-jp.com/en/10315', E'en', 43, E'Kumamoto Food Tours! Visit Farms in Yamato, Minamiaso, and Minamata', E'Kumamoto is well-known for its delicious local cuisine and specialties! We\'ll feature three food tours around Yamato, Minamiaso, and Minamata centered around organic vegetables, Akaushi beef, and Japanese black tea. Read to the end for information on how to win a prize!\n\nKumamoto Prefecture is located in the center of Kyushu. There, you\'ll find Mount Aso—one of the world’s largest volcanic calderas—that gives Kumamoto its second name: the “Land of Fire.”\n\nKumamoto is also nicknamed the “Land of Water” thanks to its mineral-rich springs. In recent years, the prefecture has gained fame as a culinary paradise. Thanks to its abundant nature and hard-working farmers, you\'ll find delicious organic vegetables, Akaushi (Japanese red cattle) beef, and freshwater fish.\n\nOur writer joined a monitoring tour of gourmet food from three areas in Kumamoto: Yamato, Minamiaso, and Minamata. We dined at a farm-to-table restaurant where dishes were made with fresh ingredients directly sourced from nearby farms. This article will showcase our experience tasting local fare!', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/20-110986.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/20-110988.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/20-110992.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/20-110990.webp"]'::jsonb, E'2021-01-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/10212', E'en', 44, E'Beppu Onsen', E'Beppu Onsen (別府温泉) is an extensive hot spring system in the city of Beppu, Ōita, Japan.\n\nThere are eight distinct  major thermal spring zones called "Beppu Hatto"（別府八湯).\n\nThere are rich hot spring resources in Beppu; the volume of water discharged from the Beppu system is second in volume to that of the Yellowstone National Park in the Western United States.\n\nThere are 2,909 hot spring vents within the city, and these account for more than 10% of the 27,644 hot spring vents in Japan, according to a survey conducted by the Ministry of the Environment in 2004.Statistics from the Beppu City Hall show that more than 130,000 tons of hot spring water gushes from the ground every day.', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108692.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110690.webp"]'::jsonb, E'2020-10-27'::timestamptz, E'Beppu Onsen', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Beppu_Onsen'),
(E'https://matcha-jp.com/en/7356', E'en', 44, E'Beppu Onsen', E'Beppu Onsen (別府温泉) is an extensive hot spring system in the city of Beppu, Ōita, Japan.\n\nThere are eight distinct  major thermal spring zones called "Beppu Hatto"（別府八湯).\n\nThere are rich hot spring resources in Beppu; the volume of water discharged from the Beppu system is second in volume to that of the Yellowstone National Park in the Western United States.\n\nThere are 2,909 hot spring vents within the city, and these account for more than 10% of the 27,644 hot spring vents in Japan, according to a survey conducted by the Ministry of the Environment in 2004.Statistics from the Beppu City Hall show that more than 130,000 tons of hot spring water gushes from the ground every day.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/10/12-148407.jpeg","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75877.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75878.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75879.webp"]'::jsonb, E'2019-05-25'::timestamptz, E'Beppu Onsen', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Beppu_Onsen'),
(E'https://matcha-jp.com/en/19845', E'en', 40, E'Kyushu', E'ɕɨ̀ɨ̀] , lit.\'nine provinces\') is the third-largest and most southerly of Japan\'s four main islands.\n\nIn the past, it has been known as Kyūkoku (九国, "Nine Countries"), Chinzei (鎮西, "West of the Pacified Area") and Tsukushi-no-shima (筑紫島, "Island of Tsukushi").\n\nThe historical regional name Saikaidō (西海道; lit.West Sea Circuit) referred to Kyushu and its surrounding islands.\n\nKyushu has a land area of 36,782 square kilometres (14,202 sq mi) and a population of 12,382,121 as of 2025.There is a theory that Kyushu was in ancient times home to its own independent dynasty, where a unique, southern-influenced culture and tradition distinct from that of Honshu flourished.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/07-246219.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/18-241500.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58455.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp"]'::jsonb, E'2024-05-21'::timestamptz, E'Kyushu', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Kyushu'),
(E'https://matcha-jp.com/en/6648', E'en', 44, E'Sightseeing in Kyushu\'s Hita City - Choose Your Own Type of Itinerary', E'Oita\'s Hita City is one of Kyushu\'s most popular travel destinations. In this article, we introduce three types of sightseeing itineraries in Hita - for the leisurely type, for the active type and for the culturally inclined type of travelers.\n\nJust one hour away from Fukuoka Airport is Oita prefecture\'s Hita City.\n\nThis city is a popular destination even within Japan. It has many highlights including hot springs amidst beautiful nature, and Mamedamachi, an area where remnants of the Edo period can still be found along its streetscapes.\n\nWhen traveling to Hita City, an area blessed with plenty of sightseeing resources, you can choose a travel style based on your personal tastes and preferences.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/06-65925.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/06-65926.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/12-66131.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/06-65927.webp"]'::jsonb, E'2018-11-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/22841', E'en', 45, E'Things to Do in Miyazaki: A Guide to the Prefecture\'s Family-Friendly Gems', E'Discover the best family-friendly attractions in beautiful Miyazaki, Japan. Enjoy pottery-making, horseback riding, and farm-to-table food. The stunning nature and hands-on experiences make for unforgettable memories. Perfect for families, couples, and solo travelers!\n\nIf you’re seeking a refreshing escape from the hustle and bustle of city life, Miyazaki Prefecture in Kyushu is a destination that caters to all, from families with children to couples and solo travelers. Its wide range of attractions, including pottery-making at Yukinotou, horseback riding at South Hill Stable, and soba-making at Kokokyan Guesthouse, provide a perfect mix of culture and fun. The stunning Ebino Highlands and serene landscapes of Mi-ike Crater Lake offer nature-lovers plenty of opportunities to unwind.\n\nFor families, it’s a treasure trove of enriching experiences set against serene mountains and lush landscapes, creating moments to bond and explore. Couples and singles, meanwhile, will appreciate the romantic charm of Miyazaki’s peaceful countryside and engaging activities. Below is a suggested two-day itinerary to help you navigate Miyazaki’s must-visit spots, ensuring a fulfilling and unforgettable trip.\n\nLunch: Visit Takachiho Farm for a farm-to-table meal and animal interaction.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211477.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211481.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211142.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/22-211456.webp"]'::jsonb, E'2024-11-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/15003', E'en', 45, E'Miyazaki\'s Nobeoka City: Sightseeing, Great Food, and Nature Near Takachiho Gorge', E'Nobeoka City in northern Miyazaki Prefecture is a great place to visit alongside the Takachiho Gorge. This article features access information, sightseeing spots, gourmet food, and events in Nobeoka―a city known for its natural scenery and traditional performing arts.\n\nNobeoka City is located in Kyushu\'s Miyazaki Prefecture. The city faces the ocean in the east and is surrounded by mountains. It boasts magnificent natural scenery and a rich history. It takes about 80 minutes to reach Nobeoka City by car within the prefecture.\n\nNobeoka offers various hands-on nature experiences related to the mountains, sea, and river. It\'s also where the original local cuisine called "Chicken Nanban" (deep-fried marinated chicken filets with tartare sauce) originated.\n\nNobeoka is situated close to the famous Takachiho Gorge. Since this spot is only an 80-minute bus ride from Nobeoka Station, Nobeoka is also the perfect spot to tour this gorge.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/10/24-150051.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/24-150052.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/15-152411.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/07-151236.webp"]'::jsonb, E'2023-12-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/25448', E'en', 45, E'Where to Visit in Japan Next: Discover Miyazaki’s Natural & Culinary Treasures', E'Discover Miyazaki, Japan’s gem on Kyushu’s coast. Home to breathtaking gorges, shrines, and immersive experiences, it’s the perfect off-the-beaten-path destination for travelers seeking nature.\n\nYou\'ve explored Tokyo’s glittering skyline, wandered Kyoto’s historic lanes, and savored Osaka’s vibrant food scene. But where should you visit in Japan next? If you’re seeking something quieter, deeper, and more authentic, Miyazaki Prefecture is the perfect off-the-beaten-path destination.\n\nMiyazaki is a stunning coastal prefecture in southeastern Kyushu that remains one of Japan’s best-kept travel secrets. Here, pristine nature meets legendary mythology, award-winning wagyu, and warm hospitality, without the crowds.\n\nThis article introduces you to Miyazaki’s must-see sights, flavors, and experiences across three main themes: nature, gourmet, and culture. Whether you’re a seasoned Japan traveler or planning your next off-the-beaten-path escape, Miyazaki is the perfect destination to rediscover what made you fall in love with Japan in the first place.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242814.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242815.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242816.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/29-242817.webp"]'::jsonb, E'2025-07-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/6679', E'en', 46, E'8 Things To Do In Sengan-en, Kagoshima: Gardens And Samurai Houses', E'Sengan-en is an iconic Japanese garden in Kagoshima. From views of Sakurajima to former samurai houses and a UNESCO World Heritage site, visitors can experience the history and culture here with all five senses. This article introduces 8 things to do.\n\nA major sightseeing spot in Kagoshima is Sengan-en. It is a large garden that spans 50,000 square meters. It takes around 40 minutes to reach from central Kagoshima via direct bus.\n\nSengan-en is known for its beauty, and visitors can also view spots, like a mansion that was the home of a feudal lord and a workshop where you can see traditional crafts. In 2018, the garden was a filming location for the Japanese Taiga drama (*1) "Segodon," gaining popularity.\n\nWe feature eight ways to enjoy Sengan-en in this article!', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65761.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65754.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/09-69126.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65759.webp"]'::jsonb, E'2019-01-20'::timestamptz, E'Sengan-en', null, null),
(E'https://matcha-jp.com/en/24865', E'en', 46, E'Sakurajima', E'Sakurajima (Japanese: 桜島, lit.\'Cherry Blossom Island\') is an active stratovolcano, formerly an island and now a peninsula, in Kagoshima Prefecture in Kyushu, Japan.\n\nIt is the most active volcano in Japan.As of November 2025, the volcanic activity continues, dropping volcanic ash on the surroundings.\n\nEarlier eruptions built the white sand highlands in the region.\n\nOn 13 September 2016, a team of experts from Bristol University and the Sakurajima Volcano Research Centre in Japan suggested that the volcano could have a major eruption within 30 years; since then many eruptions have occurred.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232922.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232888.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233503.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233504.webp"]'::jsonb, E'2025-06-12'::timestamptz, E'Sakurajima', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Sakurajima'),
(E'https://matcha-jp.com/en/19372', E'en', 46, E'Kirishima: 7 Things to Do, Hot Springs, Hiking, and Breweries', E'Kirishima is a beautiful mountainous region in Japan\'s Kagoshima Prefecture renowned for its hot spring resorts and breathtaking hiking trails. Read on to learn seven relaxing things to do in Kirishima, from hiking through one of Kyushu\'s national parks to visiting Kirishima Shrine.\n\nKirishima, located in Kagoshima Prefecture, is a region with virgin forests and rests between the mountains and the sea. Famous for hot spring resorts like Ebino Kogen and Kirishima Onsen, this beautiful destination is loved for its grand shrines and natural scenery that stays beautiful all year round.\n\nFrom the blue waters of the crater lake atop Mount Karakuni (1,700 m) to the towering cedar forests of Kirishima Shrine, there are many things to see and do in Kirishima.\n\nIf you want to spend time in nature, the Kirishima-Kinkowan National Park is a must-see when visiting Kagoshima prefecture.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/04/11-176699.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/11-176700.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/11-176713.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/16-177190.webp"]'::jsonb, E'2024-04-11'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/11504', E'en', 47, E'Okinawa Island', E'Okinawa Island (Japanese: 沖縄島, Hepburn: Okinawa-jima; Okinawan: 沖縄 / うちなー, romanized: Uchinā; Kunigami: ふちなー, romanized: Fuchináa), also known as Okinawa Main Island (沖縄本島, Okinawa-hontō), is the largest of the Okinawa Islands and the Ryukyu (Nansei) Islands of Japan in the Kyushu region.\n\n02 sq mi).It is roughly 640 kilometres (350 nmi; 400 mi) south of the main island of Kyushu and the rest of Japan.\n\nIt is 500 km (270 nmi; 310 mi) northeast of Taiwan.The total population of Okinawa Island was 1,384,762 in 2009.\n\nThe greater Naha area has roughly 800,000 residents, while the city itself has about 320,000 people.Naha is the seat of Okinawa Prefecture on the southwestern part of Okinawa Island.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/05-55738.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55846.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/09-132781.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/09-132786.webp"]'::jsonb, E'2023-02-13'::timestamptz, E'Okinawa Island', E'Wikipedia (CC BY-SA 4.0)', E'https://en.wikipedia.org/wiki/Okinawa_Island'),
(E'https://matcha-jp.com/en/12236', E'en', 47, E'Awamori, Orion Beer, and More! Okinawa Beverage Guide', E'Discover Okinawa\'s vibrant drinking culture with our guide to Awamori and Orion Beer, including the best varieties and top local izakaya bars to visit.\n\nWhen visiting Okinawa, you are bound to hear about Awamori and Orion Beer, the region\'s most famous alcoholic beverages.\n\nRead on to discover what makes these iconic local drinks so special, the top brands to look out for, and the best izakayas and distilleries to experience them during your trip.\n\nAwamori is Okinawa’s traditional distilled spirit and Japan’s oldest alcoholic beverage. Distinct from regular Japanese sake, this unique island liquor is distilled from indica rice using local black koji mold, typically yielding an alcohol content of around 30%.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/07/05-140629.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/05-140628.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/05-140630.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/05-140632.webp"]'::jsonb, E'2026-06-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/en/12186', E'en', 47, E'Okinawa\'s Shrines and Spirituality: 9 Historical Power Spots', E'Discover the spiritual side of Okinawa! Beyond the beaches and food, boost your luck at the Eight Ryukyu Shrines. Learn about Naminoue-gu, Futenma-gu, and other unique sacred sites.\n\nThroughout Japan, shrines and temples offer a window into the country\'s spirituality. Okinawa is no exception, but its local shrines possess unique characteristics found nowhere else in Japan.\n\nFor starters, while the rest of the country is home to tens of thousands of shrines, Okinawa has only about 14.\n\nFurthermore, the region follows a specific tradition known as Ryukyu Shinto. This spiritual practice was uniquely shaped by Okinawa’s distinct history and culture, setting it apart from the Shinto traditions seen on the mainland.', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/27-140040.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/27-140030.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/27-140039.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/27-140031.webp"]'::jsonb, E'2026-04-21'::timestamptz, null, null, null)
